-- Datos de ejemplo (ficticios) para StreamFlix, versión PostgreSQL (los mismos de 2-datos-ejemplo.sql)
-- Todas las cuentas de ejemplo usan la contraseña: Demo2025x
-- Cuenta principal: usuario demo2025


















-- Que los números nuevos sigan después de los de ejemplo
SELECT setval(pg_get_serial_sequence('usuarios', 'id'), COALESCE(MAX(id), 0) + 1, false) FROM usuarios;
SELECT setval(pg_get_serial_sequence('perfiles', 'id'), COALESCE(MAX(id), 0) + 1, false) FROM perfiles;
SELECT setval(pg_get_serial_sequence('generos', 'id'), COALESCE(MAX(id), 0) + 1, false) FROM generos;
SELECT setval(pg_get_serial_sequence('plataformas', 'id'), COALESCE(MAX(id), 0) + 1, false) FROM plataformas;
SELECT setval(pg_get_serial_sequence('comentarios', 'id'), COALESCE(MAX(id), 0) + 1, false) FROM comentarios;
SELECT setval(pg_get_serial_sequence('encuestas', 'id'), COALESCE(MAX(id), 0) + 1, false) FROM encuestas;
SELECT setval(pg_get_serial_sequence('historial_ia', 'id'), COALESCE(MAX(id), 0) + 1, false) FROM historial_ia;
